//! Original independently authored bounded owner behavior and failure prefixes.
use super::*;
use super::super::tests::{self as frame_tests,hooks,Hooks,cursor,retire,pin_ids,install_foreign,restore_foreign};
use frame_tests::control_tests::body_owner;
use crate::experimental_swift_reactor::allocation_tests::measure_extended;
use std::cell::{Cell,RefCell};
thread_local! {
 pub(super) static PC_OVERFLOW:Cell<bool>=const{Cell::new(false)};
 static CHECK_EXPIRE:Cell<Option<usize>>=const{Cell::new(None)};
 static CHECK_CANCEL:Cell<Option<usize>>=const{Cell::new(None)};
 static CHECKS:Cell<usize>=const{Cell::new(0)};
 static CAPACITY_FAULT:Cell<bool>=const{Cell::new(false)};
 static OBSERVE:Cell<bool>=const{Cell::new(false)};
 static ZERO:Cell<usize>=const{Cell::new(0)};
 static COPY:Cell<usize>=const{Cell::new(0)};
 static FINAL:Cell<usize>=const{Cell::new(0)};
 static FOREIGN_OLD:RefCell<Option<ReservationTicket>>=const{RefCell::new(None)};
 static ACTUAL_OLD:RefCell<Option<ReservationTicket>>=const{RefCell::new(None)};
 static SWAP_OLD:Cell<bool>=const{Cell::new(false)};
 static FIXTURES:Cell<usize>=const{Cell::new(0)};
 static STEPS:Cell<usize>=const{Cell::new(0)};
}
struct Bounds;
impl Bounds {fn new()->Self{reset();FIXTURES.with(|x|x.set(0));STEPS.with(|x|x.set(0));Self}}
impl Drop for Bounds {fn drop(&mut self){if !std::thread::panicking(){assert!(FIXTURES.with(Cell::get)<=24);assert!(STEPS.with(Cell::get)<=128);println!("MG_BOUND fixtures={} steps={} maxFixtures=24 maxSteps=128 maxFrames=3",FIXTURES.with(Cell::get),STEPS.with(Cell::get));}}}
fn reset(){hooks(Hooks::default());PC_OVERFLOW.with(|x|x.set(false));CHECK_CANCEL.with(|x|x.set(None));CHECK_EXPIRE.with(|x|x.set(None));CHECKS.with(|x|x.set(0));CAPACITY_FAULT.with(|x|x.set(false));OBSERVE.with(|x|x.set(false));ZERO.with(|x|x.set(0));COPY.with(|x|x.set(0));FINAL.with(|x|x.set(0));}
pub(super) fn growth_checkpoint(control:&RuntimeControl){let n=CHECKS.with(|x|{let n=x.get();x.set(n+1);n});if CHECK_EXPIRE.with(Cell::get)==Some(n){std::thread::sleep(control.deadline().saturating_duration_since(Instant::now())+std::time::Duration::from_millis(2));assert!(Instant::now()>=control.deadline());}if CHECK_CANCEL.with(Cell::get)==Some(n){control.cancellation().cancel();}}
pub(super) fn capacity(actual:usize)->usize{if CAPACITY_FAULT.with(Cell::get){actual+1}else{actual}}
pub(super) fn before_old_refund(_phase:&mut FrameOperationPhase<'_>,growth:&mut SwiftGrowthStorage){if SWAP_OLD.with(Cell::get){let foreign=FOREIGN_OLD.with(|x|x.borrow_mut().take());let original=std::mem::replace(&mut growth.transfer.old_ticket,foreign);ACTUAL_OLD.with(|x|*x.borrow_mut()=original);}}
pub(super) fn observe_memory(phase:&FrameOperationPhase<'_>,memory:&[u8],stage:u8){
 if !OBSERVE.with(Cell::get){return;}
 match stage {
  1=>{ZERO.with(|x|x.set(x.get()+1));assert!(memory.is_empty()||memory[memory.len()-1]==0);},
  2=>{let copied=COPY.with(|x|{let n=x.get();x.set(n+1);n*CHUNK});if copied>0{let edge=copied.min(phase.phase.parts.memory.len());assert_eq!(&memory[edge-8..edge],&phase.phase.parts.memory[edge-8..edge]);}},
  3=>{FINAL.with(|x|x.set(x.get()+1));assert_eq!(&memory[..phase.phase.parts.memory.len()],phase.phase.parts.memory.as_slice());assert!(memory[phase.phase.parts.memory.len()..].iter().all(|b|*b==0));},
  _=>unreachable!(),
 }
}
fn frame_storage<'a>()->FrameOperationStorage<'a>{FrameOperationStorage{preparation:None,entry:None,returned:None,drained:None,controlled:None}}
fn observed(p:&FrameOperationPhase<'_>)->SwiftRunUsage{p.phase.operation.control.usage(Some(p.phase.operation.wasi.usage()))}
const BODY:&[u8]=&[0x41,1,0x40,0,0x1a,0x0b];
fn fixture_with(budget:SwiftRunBudget,body:&[u8],enter:bool,action:impl for<'a> FnOnce(&mut FrameOperationPhase<'a>,&mut SwiftGrowthContext<'a>,&mut SwiftGrowthStorage)){
 FIXTURES.with(|x|x.set(x.get()+1));let mut owned=body_owner(body,false,&[],budget);let baseline=owned.control.as_ref().unwrap().usage(None).reservations.construction.current;
 let mut preparation=Some(owned.prepare_growth(cursor()));let(mut phase,mut context)=preparation.take().unwrap().unwrap();let mut growth=SwiftGrowthStorage::empty();
 if enter{phase.enter(34).unwrap();}assert_eq!(phase.phase.parts.memory.len(),584*PAGE);
 action(&mut phase,&mut context,&mut growth);reset();release_growth_pending(&mut phase,&mut context,&mut growth).unwrap();
 let report=phase.drain();assert_eq!(report.retained_frames,0);let debt=report.live_unreconciled;
 let completed=complete_growth(phase,context,growth,frame_storage(),preparation);
 if debt{assert!(matches!(completed,GrowthCompletion::Completed(FrameCompletion::Retained(_))));drop(completed);let mut owned=Some(owned);assert!(SwiftReactorInstance::cleanup_owned(&mut owned).is_err());drop(owned);}
 else{assert!(matches!(completed,GrowthCompletion::Completed(FrameCompletion::Completed)));drop(completed);assert_eq!(owned.control.as_ref().unwrap().usage(None).reservations.construction.current,baseline);retire(owned);}
}
fn fixture(action:impl for<'a> FnOnce(&mut FrameOperationPhase<'a>,&mut SwiftGrowthContext<'a>,&mut SwiftGrowthStorage)){fixture_with(SwiftRunBudget::default(),BODY,true,action)}
fn push(p:&mut FrameOperationPhase<'_>,delta:i32){p.phase.push_value(Value::I32(delta)).unwrap();}
fn op<'a>(p:&mut FrameOperationPhase<'a>,c:&mut SwiftGrowthContext<'a>,g:&mut SwiftGrowthStorage,delta:i32)->Result<(),SwiftRunFailure>{STEPS.with(|x|x.set(x.get()+1));push(p,delta);let mut slot=None;growth_operation(p,c,g,Operation::MemoryGrow,&mut slot).unwrap();slot.unwrap()}
fn seed(p:&mut FrameOperationPhase<'_>){for at in[0,CHUNK-8,PAGE-8,584*PAGE-8]{p.phase.parts.memory[at..at+8].copy_from_slice(&[9,8,7,6,5,4,3,2]);}}
#[test]fn mg01_zero_maximum_unsigned_no_allocation(){let _b=Bounds::new();for delta in[0,-1,185,i32::MAX]{fixture(|p,c,g|{push(p,delta);let before=observed(p);let ptr=p.phase.parts.memory.as_ptr();let((outer,slot),stats)=measure_extended(Some(0),||{let mut slot=None;let result=growth_operation(p,c,g,Operation::MemoryGrow,&mut slot);(result,slot)});outer.unwrap();slot.unwrap().unwrap();assert_eq!(stats.attempts,0);assert_eq!(p.phase.parts.values.as_slice(),&[Value::I32(if delta==0{584}else{-1})]);assert_eq!(p.phase.parts.memory.as_ptr(),ptr);assert_eq!(observed(p).reservations,before.reservations);assert_eq!(observed(p).execution_work-before.execution_work,2);assert_eq!(observed(p).instruction_fuel,before.instruction_fuel);assert!(g.vacant());});}}
#[test]fn mg02_success_copy_zero_and_overlap(){let _b=Bounds::new();fixture(|p,c,g|{seed(p);OBSERVE.with(|x|x.set(true));let before=observed(p);let oldticket=c.memory_ticket.as_ref().unwrap();assert!(oldticket.matches_layout(SwiftReservationCategory::State,584*PAGE));op(p,c,g,1).unwrap();assert_eq!(p.phase.parts.values.as_slice(),&[Value::I32(584)]);assert_eq!(p.phase.parts.memory.len(),585*PAGE);assert_eq!(&p.phase.parts.memory[..8],&[9,8,7,6,5,4,3,2]);assert!(p.phase.parts.memory[584*PAGE..].iter().all(|x|*x==0));assert_eq!(ZERO.with(Cell::get),585*PAGE/CHUNK);assert_eq!(COPY.with(Cell::get),584*PAGE/CHUNK);assert_eq!(FINAL.with(Cell::get),1);let after=observed(p);assert_eq!(after.execution_work-before.execution_work,3+((585+584)*PAGE)as u64);assert_eq!(after.reservations.state.current,before.reservations.state.current+PAGE);assert!(after.reservations.state.peak>=before.reservations.state.current+585*PAGE);assert_eq!(after.reservations.live_tickets,before.reservations.live_tickets);assert_eq!(after.live.memory_pages.current,585);assert!(c.memory_ticket.as_ref().unwrap().matches_layout(SwiftReservationCategory::State,585*PAGE));assert!(g.vacant());});}
#[test]fn mg03_full_767_768_overlap(){let _b=Bounds::new();fixture(|p,c,g|{op(p,c,g,183).unwrap();assert_eq!(p.phase.pop_value().unwrap(),Value::I32(584));let before=observed(p);let(_,stats)=measure_extended(None,||{op(p,c,g,1).unwrap();});assert_eq!(stats.allocations,1);assert_eq!(stats.allocated_bytes,768*PAGE);assert_eq!(stats.deallocations,1);assert_eq!(stats.freed_bytes,767*PAGE);assert_eq!(observed(p).live.memory_pages.current,768);assert!(observed(p).reservations.state.peak>=before.reservations.state.current+768*PAGE);println!("MG_OVERLAP old=767 new=768 bytes={} completeStatePeak={} stateLimit={} combinedLimit={} tickets={}",(767+768)*PAGE,observed(p).reservations.state.peak,128*1024*1024,256*1024*1024,observed(p).reservations.peak_tickets);});}
#[test]fn mg04_state_combined_before_allocator(){let _b=Bounds::new();for combined in[false,true]{fixture(|p,c,g|{push(p,1);let before=observed(p);let old=if combined{p.phase.operation.control.test_replace_combined_limit(before.reservations.combined.current+585*PAGE-1)}else{p.phase.operation.control.test_replace_state_limit(before.reservations.state.current+585*PAGE-1)};let((outer,slot),stats)=measure_extended(Some(0),||{let mut slot=None;let outer=growth_operation(p,c,g,Operation::MemoryGrow,&mut slot);(outer,slot)});outer.unwrap();let failure=slot.unwrap().unwrap_err();assert_eq!(failure.kind,if combined{SwiftRunFailureKind::CombinedExhausted}else{SwiftRunFailureKind::CategoryExhausted});assert_eq!(stats.attempts,0);assert_eq!(observed(p).live.memory_pages.current,584);assert_eq!(p.phase.parts.memory.len(),584*PAGE);assert_eq!(observed(p).reservations,before.reservations);if combined{p.phase.operation.control.test_replace_combined_limit(old);}else{p.phase.operation.control.test_replace_state_limit(old);}assert!(g.vacant());});}}
#[test]fn mg05_allocator_and_capacity_failure(){let _b=Bounds::new();for cap in[false,true]{fixture(|p,c,g|{seed(p);push(p,1);CAPACITY_FAULT.with(|x|x.set(cap));let before=observed(p);let ptr=p.phase.parts.memory.as_ptr();let((outer,slot),stats)=measure_extended(if cap{None}else{Some(0)},||{let mut slot=None;let outer=growth_operation(p,c,g,Operation::MemoryGrow,&mut slot);(outer,slot)});outer.unwrap();let failure=slot.unwrap().unwrap_err();assert_eq!(failure.kind,SwiftRunFailureKind::Allocation);assert_eq!(stats.attempts,1);assert_eq!(stats.injected_failures,usize::from(!cap));assert_eq!(stats.deallocations,usize::from(cap));assert_eq!(p.phase.parts.memory.as_ptr(),ptr);assert_eq!(observed(p).live.memory_pages.current,584);assert_eq!(observed(p).reservations.state.current,before.reservations.state.current);assert_eq!(observed(p).reservations.live_tickets,before.reservations.live_tickets);assert_eq!(&p.phase.parts.memory[..8],&[9,8,7,6,5,4,3,2]);assert!(g.vacant());});}}
#[test]fn mg06_work_prefix_and_postcommit_push(){let _b=Bounds::new();let growthwork=((584+585)*PAGE)as u64;for allowed in[0,1,1+growthwork,2+growthwork]{fixture(|p,c,g|{push(p,1);let before=observed(p);let limit=p.phase.operation.control.test_replace_execution_work_limit(before.execution_work+allowed);let mut slot=None;growth_operation(p,c,g,Operation::MemoryGrow,&mut slot).unwrap();p.phase.operation.control.test_replace_execution_work_limit(limit);let committed=allowed>=1+growthwork;assert_eq!(p.phase.parts.memory.len(),if committed{585*PAGE}else{584*PAGE});assert_eq!(observed(p).live.memory_pages.current,if committed{585}else{584});assert_eq!(slot.unwrap().is_ok(),allowed>=2+growthwork);assert_eq!(p.phase.parts.values.len(),usize::from(allowed==0||allowed>=2+growthwork));assert!(g.vacant());});}}
#[test]fn mg07_cancel_zero_copy_final_prefix(){let _b=Bounds::new();let zero=585*PAGE/CHUNK;let copy=584*PAGE/CHUNK;for checkpoint in[0,1,2,3,2+zero,3+zero,2+zero+copy]{fixture(|p,c,g|{seed(p);push(p,1);OBSERVE.with(|x|x.set(true));CHECK_CANCEL.with(|x|x.set(Some(checkpoint)));let before=observed(p);let ptr=p.phase.parts.memory.as_ptr();let mut slot=None;growth_operation(p,c,g,Operation::MemoryGrow,&mut slot).unwrap();let failure=slot.unwrap().unwrap_err();assert_eq!(failure.kind,SwiftRunFailureKind::Cancelled);assert_eq!(p.phase.parts.memory.as_ptr(),ptr);assert_eq!(p.phase.parts.memory.len(),584*PAGE);assert_eq!(&p.phase.parts.memory[..8],&[9,8,7,6,5,4,3,2]);assert_eq!(observed(p).live.memory_pages.current,584);assert_eq!(observed(p).reservations.state.current,before.reservations.state.current);assert!(g.vacant());assert_eq!(CHECKS.with(Cell::get),checkpoint+1);assert_eq!(ZERO.with(Cell::get),(checkpoint.saturating_sub(1)).min(zero));assert_eq!(COPY.with(Cell::get),(checkpoint.saturating_sub(1+zero)).min(copy));assert_eq!(FINAL.with(Cell::get),usize::from(checkpoint==2+zero+copy));});}}
#[test]fn mg08_preflight_frame_type_and_ticket(){let _b=Bounds::new();for fault in 0..7{fixture(|p,c,g|{push(p,1);let scalar=(p.phase.parts.frames[0].base,p.phase.parts.frames[0].operands,p.phase.parts.frames[0].controls);let mut ticket=None;match fault{0=>p.phase.parts.values[0]=Value::I64(1),1=>p.phase.parts.frames[0].operands=1,2=>p.phase.parts.frames[0].base=1,3=>p.phase.parts.frames[0].controls=99,4=>ticket=c.memory_ticket.take(),5=>{p.phase.parts.memory.pop();},_=>p.terminal()};let before=observed(p);let mut slot=None;growth_operation(p,c,g,Operation::MemoryGrow,&mut slot).unwrap();assert!(slot.unwrap().is_err());assert_eq!(p.phase.parts.values.len(),1);assert_eq!(observed(p).execution_work,before.execution_work);let f=&mut p.phase.parts.frames[0];(f.base,f.operands,f.controls)=scalar;if fault==4{*c.memory_ticket=ticket;}if fault==5{p.phase.parts.memory.push(0);}});}fixture_with(SwiftRunBudget::default(),BODY,false,|p,c,g|{let mut slot=None;growth_operation(p,c,g,Operation::MemoryGrow,&mut slot).unwrap();assert_eq!(slot.unwrap().unwrap_err().code,"swift_growth_frame_missing");});}
#[test]fn mg09_actual_pinned_cursor_pc_fuel(){let _b=Bounds::new();fixture(|p,c,g|{seed(p);push(p,1);p.phase.parts.frames[0].pc=1;let pins=pin_ids(p);let selected={let f=&p.phase.parts.frames[0];p.phase.parts.cache.view(&f.pin,p.phase.operation.control,Some(&*p.phase.operation.wasi)).unwrap().instructions[1]};let before=observed(p);let mut storage=frame_storage();growth_pinned_caller(p,c,g,&mut storage).unwrap();assert_eq!(storage.entry,Some(Ok(())));assert_eq!(p.phase.parts.frames[0].pc,2);assert_eq!(pin_ids(p),pins);assert_eq!(p.phase.operation.cursor.function,Some(34));assert_eq!(p.phase.operation.cursor.offset,Some(selected.offset));assert_eq!(observed(p).instructions-before.instructions,1);assert_eq!(observed(p).instruction_fuel-before.instruction_fuel,1);assert_eq!(observed(p).execution_work-before.execution_work,3+((584+585)*PAGE)as u64);});}
#[test]fn mg10_pinned_failures_before_effects(){let _b=Bounds::new();for fault in 0..5{fixture(|p,c,g|{push(p,1);p.phase.parts.frames[0].pc=1;let previous=if fault==3{Some(p.phase.operation.control.test_replace_execution_work_limit(observed(p).execution_work))}else{None};match fault{0=>p.phase.operation.control.cancellation().cancel(),1=>PC_OVERFLOW.with(|x|x.set(true)),2=>p.phase.parts.frames[0].pc=usize::MAX,4=>p.phase.parts.frames[0].pc=0,_=>{}}let before=observed(p);let mut storage=frame_storage();growth_pinned_caller(p,c,g,&mut storage).unwrap();assert!(storage.entry.unwrap().is_err());assert_eq!(p.phase.parts.values.len(),1);assert_eq!(p.phase.parts.memory.len(),584*PAGE);if fault==0{assert_eq!(observed(p).instructions,before.instructions);}if let Some(previous)=previous{p.phase.operation.control.test_replace_execution_work_limit(previous);}});}fixture_with(SwiftRunBudget{instruction_fuel:0,..SwiftRunBudget::default()},BODY,true,|p,c,g|{push(p,1);p.phase.parts.frames[0].pc=1;let before=observed(p);let mut s=frame_storage();growth_pinned_caller(p,c,g,&mut s).unwrap();assert_eq!(s.entry.unwrap().unwrap_err().kind,SwiftRunFailureKind::FuelExhausted);assert_eq!(p.phase.parts.frames[0].pc,1);assert_eq!(observed(p).execution_work,before.execution_work);});}
