#[test]fn mg12_ticket_retention_retry_refusal(){let _b=Bounds::new();FIXTURES.with(|x|x.set(x.get()+2));let mut foreign=body_owner(BODY,false,&[],SwiftRunBudget::default());let mut foreign_ticket=foreign.state.as_mut().unwrap().buffers[3].take();let mut own=body_owner(BODY,false,&[],SwiftRunBudget::default());let before=own.control.as_ref().unwrap().usage(None).reservations.construction.current;let mut preparation=Some(own.prepare_growth(cursor()));let(mut p,mut c)=preparation.take().unwrap().unwrap();p.enter(34).unwrap();let mut growth=SwiftGrowthStorage::empty();growth.transfer.next_pages=584;growth.transfer.ticket=Some(p.phase.operation.control.admit_with_wasi(SwiftReservationCategory::State,584*PAGE,p.phase.operation.cursor,Some(p.phase.operation.wasi.usage())).unwrap());let original=growth.transfer.ticket.take();growth.transfer.ticket=foreign_ticket.take();let ledger=observed(&p).reservations;let failure=release_growth_pending(&mut p,&mut c,&mut growth).unwrap_err();assert_eq!(failure.code,"swift_run_reservation_owner");assert!(growth.transfer.ticket.is_some());assert_eq!(observed(&p).reservations,ledger);let completion=complete_growth(p,c,growth,frame_storage(),preparation);let(mut p,mut c,mut growth,storage,preparation)=match completion{GrowthCompletion::Retained{phase,context,growth,storage,preparation}=>(phase,context,growth,storage,preparation),_=>panic!("lost actual authority")};assert!(observed(&p).reservations.construction.current>before);foreign_ticket=growth.transfer.ticket.take();growth.transfer.ticket=original;release_growth_pending(&mut p,&mut c,&mut growth).unwrap();assert!(growth.vacant());p.drain();assert!(matches!(complete_growth(p,c,growth,storage,preparation),GrowthCompletion::Completed(FrameCompletion::Completed)));foreign.state.as_mut().unwrap().buffers[3]=foreign_ticket;retire(foreign);retire(own);}
#[test]fn mg13_result_push_failure_committed_and_pin_retry(){let _b=Bounds::new();fixture(|p,c,g|{push(p,1);hooks(Hooks{push_fault:2,..Hooks::default()});let mut slot=None;growth_operation(p,c,g,Operation::MemoryGrow,&mut slot).unwrap();assert_eq!(slot.unwrap().unwrap_err().kind,SwiftRunFailureKind::ValueLimit);assert_eq!(p.phase.parts.memory.len(),585*PAGE);assert_eq!(observed(p).live.memory_pages.current,585);assert!(c.memory_ticket.as_ref().unwrap().matches_layout(SwiftReservationCategory::State,585*PAGE));assert!(g.vacant());});FIXTURES.with(|x|x.set(x.get()+2));let mut foreign=body_owner(BODY,false,&[],SwiftRunBudget::default());install_foreign(&mut foreign);let mut own=body_owner(BODY,false,&[],SwiftRunBudget::default());let mut prep=Some(own.prepare_growth(cursor()));let(mut p,mut c)=prep.take().unwrap().unwrap();p.enter(34).unwrap();p.enter(36).unwrap();p.enter(34).unwrap();let mut g=SwiftGrowthStorage::empty();CHECK_CANCEL.with(|x|x.set(Some(3)));let failure=op(&mut p,&mut c,&mut g,1).unwrap_err();let pins=pin_ids(&p);hooks(Hooks{release_mask:7,..Hooks::default()});assert_eq!(p.drain().retained_frames,3);assert_eq!(pin_ids(&p),pins);reset();assert!(matches!(complete_growth(p,c,g,frame_storage(),prep),GrowthCompletion::Completed(FrameCompletion::Retained(_))));let mut resumed=Some(own.resume_frame_cleanup());let mut p=resumed.take().unwrap().unwrap();let report=p.drain();assert_eq!(report.retained_frames,0);assert_eq!(report.first_failure.unwrap().code,failure.code);assert!(matches!(p.complete(FrameOperationStorage{preparation:resumed,..frame_storage()}),FrameCompletion::Completed));restore_foreign(&mut foreign);retire(foreign);retire(own);}
