#[test]fn mg15_narrowed_maximum_and_fuel_work(){let _b=Bounds::new();fixture_with(SwiftRunBudget{memory_pages:584,..SwiftRunBudget::default()},BODY,true,|p,c,g|{op(p,c,g,1).unwrap();assert_eq!(p.phase.parts.values.as_slice(),&[Value::I32(-1)]);assert_eq!(p.phase.parts.memory.len(),584*PAGE);assert!(g.vacant());});fixture(|p,c,g|{push(p,0);p.phase.parts.frames[0].pc=1;let before=observed(p);let mut s=frame_storage();growth_pinned_caller(p,c,g,&mut s).unwrap();assert_eq!(s.entry,Some(Ok(())));assert_eq!(observed(p).instruction_fuel-before.instruction_fuel,1);assert_eq!(observed(p).execution_work-before.execution_work,3);assert_eq!(p.phase.parts.values.as_slice(),&[Value::I32(584)]);});}
