#[test]fn mg17_old_refund_postcommit_retained_retry(){let _b=Bounds::new();FIXTURES.with(|x|x.set(x.get()+1));let mut foreign=body_owner(BODY,false,&[],SwiftRunBudget::default());FOREIGN_OLD.with(|x|*x.borrow_mut()=foreign.state.as_mut().unwrap().buffers[3].take());fixture(|p,c,g|{SWAP_OLD.with(|x|x.set(true));let before=observed(p);let failure=op(p,c,g,1).unwrap_err();SWAP_OLD.with(|x|x.set(false));assert_eq!(failure.code,"swift_run_reservation_owner");assert_eq!(p.phase.parts.memory.len(),585*PAGE);assert_eq!(observed(p).live.memory_pages.current,585);assert!(g.transfer.old_ticket.is_some());assert_eq!(g.transfer.old.capacity(),0);assert_eq!(g.pages_debited,0);assert_eq!(observed(p).reservations.state.current,before.reservations.state.current+585*PAGE);assert!(c.memory_ticket.as_ref().unwrap().matches_layout(SwiftReservationCategory::State,585*PAGE));let foreign=g.transfer.old_ticket.take();FOREIGN_OLD.with(|x|*x.borrow_mut()=foreign);g.transfer.old_ticket=ACTUAL_OLD.with(|x|x.borrow_mut().take());release_growth_pending(p,c,g).unwrap();assert!(g.vacant());assert_eq!(observed(p).reservations.state.current,before.reservations.state.current+PAGE);assert_eq!(p.invariant("later").code,failure.code);});foreign.state.as_mut().unwrap().buffers[3]=FOREIGN_OLD.with(|x|x.borrow_mut().take());retire(foreign);}
#[test]fn mg18_sticky_uncommitted_debt_refuses_completion(){let _b=Bounds::new();FIXTURES.with(|x|x.set(x.get()+1));let mut own=body_owner(BODY,false,&[],SwiftRunBudget::default());let mut prep=Some(own.prepare_growth(cursor()));let(mut p,mut c)=prep.take().unwrap().unwrap();p.enter(34).unwrap();let mut g=SwiftGrowthStorage::empty();g.transfer.next_pages=585;g.transfer.ticket=Some(p.phase.operation.control.admit_with_wasi(SwiftReservationCategory::State,585*PAGE,p.phase.operation.cursor,Some(p.phase.operation.wasi.usage())).unwrap());g.pages_debited=1;p.phase.operation.control.remove_live(Live::MemoryPages,584).unwrap();let ledger=observed(&p).reservations;assert_eq!(release_growth_pending(&mut p,&mut c,&mut g).unwrap_err().code,"swift_run_live_underflow");assert!(g.live_unreconciled);assert!(g.transfer.ticket.is_some());assert_eq!(observed(&p).reservations,ledger);assert!(release_growth_pending(&mut p,&mut c,&mut g).is_err());assert!(g.transfer.ticket.is_some());let completed=complete_growth(p,c,g,frame_storage(),prep);match &completed{GrowthCompletion::Retained{phase,growth,..}=>{assert!(growth.transfer.ticket.is_some());assert!(growth.live_unreconciled);assert_eq!(observed(phase).reservations,ledger);},_=>panic!("lost page debt authority")};drop(completed);let mut owned=Some(own);assert!(SwiftReactorInstance::cleanup_owned(&mut owned).is_err());assert!(owned.is_some());drop(owned);println!("MG_DEBT exact original N and envelope retained until deliberate test-owner drop; no accounting repair or clean receipt");}
#[test]fn mg19_actual_deadline_at_growth_boundary(){let _b=Bounds::new();let final_check=2+585*PAGE/CHUNK+584*PAGE/CHUNK;for(cancel,checkpoint)in[(false,2),(false,final_check),(true,2)]{fixture_with(SwiftRunBudget{deadline_ms:1000,..SwiftRunBudget::default()},BODY,true,|p,c,g|{push(p,1);CHECK_EXPIRE.with(|x|x.set(Some(checkpoint)));if cancel{CHECK_CANCEL.with(|x|x.set(Some(checkpoint)));}let mut slot=None;growth_operation(p,c,g,Operation::MemoryGrow,&mut slot).unwrap();let failure=slot.unwrap().unwrap_err();assert_eq!(failure.kind,if cancel{SwiftRunFailureKind::Cancelled}else{SwiftRunFailureKind::Deadline});assert_eq!(failure.deadline_origin,SwiftDeadlineOrigin::Run);assert!(failure.at_failure.deadline_overshoot_micros>0);assert_eq!(p.phase.parts.memory.len(),584*PAGE);assert_eq!(observed(p).live.memory_pages.current,584);assert!(g.vacant());println!("MG_DEADLINE checkedBoundary={} cancel={} origin={:?} overshootMicros={}",checkpoint,cancel,failure.deadline_origin,failure.at_failure.deadline_overshoot_micros);});}}
#[cfg(feature="experimental-span-execution")]
#[test]fn mg20_frozen_targeted_growth_semantics(){let _b=Bounds::new();use crate::experimental::{cache::{FunctionCache,CacheBudget},execution::{SpanInstance,ExecutionBudget},validate_spans,ValidationBudget};for(delta,encoded,answer,pages)in[(0,0,1,1),(1,1,1,2),(2,2,1,3),(3,3,-1,1),(-1,0x7f,-1,1)]{let body=[0,0x41,encoded,0x40,0,0x0b];let mut bytes=b"\0asm\x01\0\0\0".to_vec();bytes.extend_from_slice(&[1,5,1,0x60,0,1,0x7f,3,2,1,0,5,4,1,1,1,3,7,7,1,3,b'r',b'u',b'n',0,0,10,8,1,6]);bytes.extend_from_slice(&body);let limits=crate::Limits{profile:crate::Profile::TableMemoryV3,..crate::Limits::default()};let cancel=crate::Cancellation::default();let spans=validate_spans(&bytes,limits,ValidationBudget::default(),&cancel).unwrap();let cache=FunctionCache::new(spans,CacheBudget::default(),&cancel).unwrap();let mut frozen=SpanInstance::new(cache,ExecutionBudget::default(),cancel).unwrap();assert_eq!(frozen.invoke("run",&[]).unwrap(),Some(Value::I32(answer)));assert_eq!(frozen.memory().len(),pages*PAGE);assert!(frozen.memory().iter().all(|byte|*byte==0));println!("MG_FROZEN delta={} answer={} pages={} work={} fuel={}",delta,answer,pages,frozen.usage().work_used,frozen.usage().fuel_used);}}

#[test] fn cdr04_actual_pinned_growth_pop_attribution(){let _b=Bounds::new();fixture(|p,c,g|{push(p,1);p.phase.parts.frames[0].pc=1;let actual={let f=&p.phase.parts.frames[0];p.phase.parts.cache.view(&f.pin,p.phase.operation.control,Some(&*p.phase.operation.wasi)).unwrap().instructions[1]};hooks(Hooks{push_fault:5,..Hooks::default()});let mut s=frame_storage();growth_pinned_caller(p,c,g,&mut s).unwrap();let failure=s.entry.unwrap().unwrap_err();assert_eq!((failure.stage,failure.function,failure.offset,failure.resource),(SwiftRunStage::Invocation,Some(34),Some(actual.offset),Some(SwiftRunResource::Values)));assert_eq!((failure.attempted,failure.limit),(1,0));assert!(p.cleanup.live_unreconciled);assert_eq!(p.phase.parts.memory.len(),584*PAGE);assert!(g.vacant());});}
